const folders = new Map<string, FileEntryData[]>()
for (const entry of entries) folders.set(folderOf(entry.path), [...(folders.get(folderOf(entry.path)) ?? []), entry])
return [...folders].map(([path, files]) => ({ path, files }))

this.store.change(({ fileBar, openPath }) => {
  const openFolders = view === 'folders' && openPath ? [...new Set([...fileBar.openFolders, folderOf(openPath)])] : fileBar.openFolders
  return { fileBar: { ...fileBar, view, openFolders } }
})

this.store.change(({ fileBar }) => {
  const isOpen = fileBar.openFolders.includes(path)
  return { fileBar: { ...fileBar, openFolders: isOpen ? fileBar.openFolders.filter(each => each !== path) : [...fileBar.openFolders, path] } }
})

const classes = ['file-entry', isOpen ? 'is-open' : '', entry.exists ? '' : 'is-missing', entry.is_changed ? 'is-changed' : ''].filter(Boolean).join(' ')
const hint = isDrawio(entry.path) ? `${entry.path}: opens in the draw.io viewer` : entry.exists ? entry.path : `${entry.path}: not generated yet`
return (
  <li>
    <button className={classes} title={hint} aria-current={isOpen ? 'true' : undefined} disabled={!entry.exists} onClick={() => void page.open(entry.path)}>
      {fileNameOf(entry.path)}
      {isDrawio(entry.path) ? <span className="file-entry-note"> ↗ draw.io</span> : null}
    </button>
  </li>
)

const state = useFilesState(page)
if (state.isListing) return <p className="files-note">Reading the files…</p>
if (!state.entries.length) return <p className="files-note">No files here yet.</p>
if (state.fileBar.view === 'folders') return <FileFoldersView page={page} />
return (
  <ul className="file-list" aria-label="Files">
    {state.entries.map(entry => (
      <FileEntryView key={entry.path} page={page} entry={entry} isOpen={entry.path === state.openPath} />
    ))}
  </ul>
)

const { openPath } = useFilesState(page)
return (
  <ul className="file-folders" aria-label="Folders">
    {page.fileBar.folders.map(folder => {
      const isOpen = page.fileBar.isOpen(folder)
      return (
        <li key={folder.path}>
          <button className="file-folder" title={folder.path || 'the project folder'} aria-expanded={isOpen} onClick={() => page.fileBar.toggleFolder(folder.path)}>
            <span className="file-folder-mark">{isOpen ? '▾' : '▸'}</span> {folder.path || '/'} <span className="file-entry-note">{folder.files.length}</span>
          </button>
          {isOpen ? (
            <ul className="file-list">
              {folder.files.map(entry => (
                <FileEntryView key={entry.path} page={page} entry={entry} isOpen={entry.path === openPath} />
              ))}
            </ul>
          ) : null}
        </li>
      )
    })}
  </ul>
)

const { fileBar } = useFilesState(page)
return (
  <div className="file-bar-buttons" role="toolbar" aria-label="File bar">
    <button aria-label={fileBar.isOpen ? 'Collapse the file bar' : 'Expand the file bar'} title={fileBar.isOpen ? 'Collapse the file bar' : 'Expand the file bar'} onClick={() => page.fileBar.toggle()}>
      {fileBar.isOpen ? '«' : '»'}
    </button>
    {fileBar.isOpen ? (
      <>
        <button className="file-bar-view" aria-pressed={fileBar.view === 'list'} title="Show the files as a list" onClick={() => page.fileBar.show('list')}>
          List
        </button>
        <button className="file-bar-view" aria-pressed={fileBar.view === 'folders'} title="Show the files in their folders" onClick={() => page.fileBar.show('folders')}>
          Folders
        </button>
      </>
    ) : null}
  </div>
)

const { practices } = useFilesState(page)
if (!practices.length) return null
return (
  <div className="practice-toggles" role="group" aria-label="Practices">
    {practices.map(practice => (
      <button
        key={practice.name}
        className={`practice-toggle ${practice.enabled ? 'is-on' : 'is-off'}`}
        style={{ '--practice-colour': practice.colour } as CSSProperties}
        aria-pressed={practice.enabled}
        title={`${practice.short_name}: ${practice.enabled ? 'on, press to hide its files' : 'off, press to show its files'}`}
        onClick={() => void page.togglePractice(practice.name)}
      >
        {practice.short_name}
      </button>
    ))}
  </div>
)

const open = file.comments.filter(comment => comment.state === 'not_sent').length
const processed = file.comments.filter(comment => comment.state === 'processed').length
return (
  <div className="comment-toolbar">
    <button disabled={!open} onClick={() => void page.comments.sendOpen()}>
      Send all open comments{open ? ` (${open})` : ''}
    </button>
    <button disabled={!processed} onClick={() => void page.comments.clearProcessed()}>
      Clear processed{processed ? ` (${processed})` : ''}
    </button>
    <span className="files-hint">Select lines, right-click, Add comment</span>
  </div>
)

const state = useFilesState(page)
if (!state.openPath) return <p className="files-note">Choose a file.</p>
if (!state.file) return <p className="files-note">Opening {state.openPath}…</p>
return (
  <section className="open-file" aria-label={state.file.path}>
    <CommentToolbarView page={page} file={state.file} />
    <FileSourceView key={state.file.path} file={state.file} actions={page.comments} />
  </section>
)

const { toasts } = useFilesState(page)
return (
  <div className="toasts" role="status">
    {toasts.map(text => (
      <div key={text} className="toast">
        {text}
      </div>
    ))}
  </div>
)

if (!this.state.failure) return this.props.children
return (
  <main className="files-page">
    <div className="files-problem" role="alert">
      The Files page stopped: {this.state.failure}
    </div>
  </main>
)

void this.list()
const reread = () => void Promise.all([this.refreshOpen(), this.readPractices()])
window.addEventListener('focus', reread)
const practicesTimer = setInterval(() => {
  if (document.visibilityState === 'visible') void this.readPractices({ isQuiet: true })
}, PRACTICES_REFRESH_MILLISECONDS)
return () => {
  window.removeEventListener('focus', reread)
  clearInterval(practicesTimer)
  this.stopRefreshing()
}

if (!this.link.namesFiles) return this.store.change(() => ({ isListing: false, problem: 'This link names no files: open the Files app from the chat bar.' }))
try {
  const [byFidelity] = await Promise.all([this.filesByFidelity(), this.readPractices()])
  this.store.change(state => ({ byFidelity, entries: filesShown(byFidelity, state.practices), isListing: false }))
  const entries = this.state.entries
  // A .drawio file opens in a tab of its own only on a click, so a link naming one opens the first other file here.
  const named = isDrawio(this.link.file) ? '' : this.link.file
  const first = named || entries.find(entry => entry.exists && !isDrawio(entry.path))?.path || ''
  if (first) await this.open(first)
} catch (failure) {
  this.store.change(() => ({ isListing: false, problem: `The files did not list: ${reasonOf(failure)}` }))
}

if (this.link.isSessionFolder) return [{ slug: '', entries: (await this.session.folderFiles()) ?? [] }]
return Promise.all(
  this.link.fidelities.map(async slug => ({ slug, entries: Object.values((await FidelityProgressClientGenerated.named(this.api, this.link.ticket, slug).files()) ?? {}).flat() })),
)

try {
  const shown = await this.session.show()
  const practices = Object.values(shown?.practices ?? {})
  if (this.state.practices.length && onOff(practices) === onOff(this.state.practices)) return
  this.store.change(state => ({ practices, entries: filesShown(state.byFidelity, practices) }))
} catch (failure) {
  if (!isQuiet) this.toast(`The session's practices did not load: ${reasonOf(failure)}`)
}

const practice = this.state.practices.find(each => each.name === name)
if (!practice) return
const isTurnedOn = await this.attemptQuietly(`${practice.short_name} was not turned ${practice.enabled ? 'off' : 'on'}`, () =>
  PracticeSessionOutputClientGenerated.named(this.api, this.link.sessionFile, name).enable(!practice.enabled),
)
if (!isTurnedOn) return
await this.readPractices()
if (this.link.chat) await this.attemptQuietly('The chat bar was not told to show the change', () => ChatClientGenerated.named(this.api, this.link.chat).send('refresh', 'practices'))

if (isDrawio(path)) return this.openDrawio(path)
this.store.change(() => ({ openPath: path, file: null }))
await this.refreshOpen()

const path = this.state.openPath
if (!path) return
this.stopRefreshing()
try {
  const file = await this.session.file(path)
  if (this.state.openPath !== path) return
  this.store.change(() => ({ file, problem: '' }))
  if (file?.comments.some(comment => comment.state === 'sent')) this.refreshTimer = setTimeout(() => void this.refreshOpen(), SENT_REFRESH_MILLISECONDS)
} catch (failure) {
  this.store.change(() => ({ problem: `${path} did not open: ${reasonOf(failure)}` }))
}

const tab = this.openTab()
try {
  const opened = await this.api.post<{ url: string }>(DRAWIO_PATH, { path })
  if (!opened?.url) throw new Error('the viewer sent back no address')
  if (!tab) return this.toast(`${path} did not open in the draw.io viewer: the browser refused a new tab`)
  tab.location.href = opened.url
} catch (failure) {
  tab?.close()
  this.toast(`${path} did not open in the draw.io viewer: ${reasonOf(failure)}`)
}
